import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int[] parent, rank;

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void union(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (rank[a] < rank[b]) {
            int tmp = a;
            a = b;
            b = tmp;
        }
        parent[b] = a;
        if (rank[a] == rank[b]) rank[a]++;
    }

    static boolean intersect(int x1, int y1, int x2, int y2, int a1, int b1, int a2, int b2) {
        return Math.max(x1, a1) <= Math.min(x2, a2) &&
               Math.max(y1, b1) <= Math.min(y2, b2);
    }

    static long pointRectDist(int x, int y, int x1, int y1, int x2, int y2) {
        long dx = 0;
        if (x < x1) dx = x1 - x;
        else if (x > x2) dx = x - x2;

        long dy = 0;
        if (y < y1) dy = y1 - y;
        else if (y > y2) dy = y - y2;

        return dx + dy;
    }

    static long rectDist(int x1, int y1, int x2, int y2, int a1, int b1, int a2, int b2) {
        long dx = 0;
        if (x2 < a1) dx = a1 - x2;
        else if (a2 < x1) dx = x1 - a2;

        long dy = 0;
        if (y2 < b1) dy = b1 - y2;
        else if (b2 < y1) dy = y1 - b2;

        return dx + dy;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int Xi = fs.nextInt();
        int Yi = fs.nextInt();
        int Xf = fs.nextInt();
        int Yf = fs.nextInt();

        int N = fs.nextInt();

        int[] x1 = new int[N], y1 = new int[N], x2 = new int[N], y2 = new int[N];

        for (int i = 0; i < N; i++) {
            x1[i] = fs.nextInt();
            y1[i] = fs.nextInt();
            x2[i] = fs.nextInt();
            y2[i] = fs.nextInt();
        }

        parent = new int[N];
        rank = new int[N];
        for (int i = 0; i < N; i++) parent[i] = i;

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (intersect(x1[i], y1[i], x2[i], y2[i], x1[j], y1[j], x2[j], y2[j])) {
                    union(i, j);
                }
            }
        }

        int[] comp = new int[N];
        int[] rootToComp = new int[N];
        Arrays.fill(rootToComp, -1);

        int M = 0;
        for (int i = 0; i < N; i++) {
            int r = find(i);
            if (rootToComp[r] == -1) rootToComp[r] = M++;
            comp[i] = rootToComp[r];
        }

        int S = M;
        int T = M + 1;
        int V = M + 2;

        long INF = Long.MAX_VALUE / 4;
        long[][] graph = new long[V][V];

        for (int i = 0; i < V; i++) {
            Arrays.fill(graph[i], INF);
            graph[i][i] = 0;
        }

        for (int i = 0; i < N; i++) {
            int c = comp[i];

            long ds = pointRectDist(Xi, Yi, x1[i], y1[i], x2[i], y2[i]);
            if (ds < graph[S][c]) {
                graph[S][c] = ds;
                graph[c][S] = ds;
            }

            long de = pointRectDist(Xf, Yf, x1[i], y1[i], x2[i], y2[i]);
            if (de < graph[T][c]) {
                graph[T][c] = de;
                graph[c][T] = de;
            }
        }

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                int ci = comp[i];
                int cj = comp[j];
                if (ci != cj) {
                    long d = rectDist(x1[i], y1[i], x2[i], y2[i], x1[j], y1[j], x2[j], y2[j]);
                    if (d < graph[ci][cj]) {
                        graph[ci][cj] = d;
                        graph[cj][ci] = d;
                    }
                }
            }
        }

        graph[S][T] = graph[T][S] = Math.abs(Xi - Xf) + Math.abs(Yi - Yf);

        long[] dist = new long[V];
        Arrays.fill(dist, INF);
        dist[S] = 0;

        boolean[] used = new boolean[V];

        for (int iter = 0; iter < V; iter++) {
            int u = -1;
            long best = INF;

            for (int i = 0; i < V; i++) {
                if (!used[i] && dist[i] < best) {
                    best = dist[i];
                    u = i;
                }
            }

            if (u == -1) break;
            used[u] = true;
            if (u == T) break;

            for (int v = 0; v < V; v++) {
                if (!used[v] && graph[u][v] < INF) {
                    long nd = dist[u] + graph[u][v];
                    if (nd < dist[v]) dist[v] = nd;
                }
            }
        }

        System.out.println(dist[T]);
    }
}
